arguments.query_string:
query EGFRDrugs($ensemblId: String!) {
  target(ensemblId: $ensemblId) {
    id
    approvedSymbol
    drugAndClinicalCandidates {
      count
      rows {
        maxClinicalStage
        drug {
          id
          name
          drugType
          maximumClinicalStage
        }
        diseases {
          diseaseFromSource
          disease { id name }
        }
      }
    }
  }
}
